async function ensureRiderLobby(){
  if(!supabaseClient)return false;
  if(riderLobbySubscribed)return true;
  if(riderLobbyReady){
    const ready=await riderLobbyReady;
    if(ready||riderLobbySubscribed)return true;
    try{riderLobbyChannel?.unsubscribe?.()}catch{}
    riderLobbyChannel=null;riderLobbyReady=null;riderLobbySubscribed=false
  }
  const id=localRiderId();
  riderLobbyReady=new Promise(resolve=>{
    let settled=false;const finish=v=>{if(settled)return;settled=true;resolve(v)};
    const channel=supabaseClient.channel('rider-voz-lobby-v2',{config:{presence:{key:id},broadcast:{self:false}}});
    riderLobbyChannel=channel;
    channel.on('presence',{event:'sync'},()=>{}).subscribe(async status=>{
      if(status==='SUBSCRIBED'){
        riderLobbySubscribed=true;
        try{await channel.track({id,alias:localRiderAlias(),online_at:new Date().toISOString(),device:'android'})}catch{}
        finish(true)
      }
      if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){
        riderLobbySubscribed=false;
        if(riderLobbyChannel===channel)riderLobbyChannel=null;
        finish(false)
      }
    });
    setTimeout(()=>finish(riderLobbySubscribed),4500)
  });
  const ready=await riderLobbyReady;
  if(!ready&&!riderLobbySubscribed)riderLobbyReady=null;
  return ready||riderLobbySubscribed
}
async function updateRiderLobby(){
  if(!await ensureRiderLobby())return false;
  try{await riderLobbyChannel.track({id:localRiderId(),alias:localRiderAlias(),online_at:new Date().toISOString(),device:'android'});return true}catch{return false}
}
