async function recoverPendingVoiceInvite(){
  if(!supabaseClient)return false;
  const me=await authUserId();if(!me)return false;
  try{
    const now=new Date().toISOString();
    const {data,error}=await supabaseClient.from('voice_invites').select('id,sender_id,session_id,created_at,expires_at').eq('recipient_id',me).eq('status','pending').gt('expires_at',now).order('created_at',{ascending:false}).limit(1).maybeSingle();
    if(error||!data)return false;
    if(!data.session_id){await updateVoiceInviteRecord(data.id,'expired');return false}
    const createdAt=new Date(data.created_at).getTime();
    return await showVoiceInvite({from:data.sender_id,to:me,sessionId:data.session_id,inviteId:data.id,createdAt},voiceInboxChannel)
  }catch{return false}
}
async function ensureVoiceInbox(){
  if(!supabaseClient)return false;
  const me=voiceUserId();if(!me)return false;
  if(voiceInboxChannel&&voiceInboxIdentity===me&&voiceInboxReady){
    const ready=await voiceInboxReady;if(ready)return true
  }
  if(voiceInboxChannel){try{voiceInboxChannel.unsubscribe()}catch{}}
  const channel=supabaseClient.channel('rider-voice-inbox-'+me,{config:{broadcast:{self:false}}});
  voiceInboxChannel=channel;voiceInboxIdentity=me;
  channel.on('broadcast',{event:'voice-invite'},({payload})=>{showVoiceInvite(payload,channel)}).on('broadcast',{event:'voice-invite-response'},({payload})=>{if(!payload?.sessionId)return;const handler=pendingVoiceResponses.get(payload.sessionId);if(handler)handler(payload)});
  voiceInboxReady=new Promise(resolve=>{
    let settled=false;const finish=value=>{if(settled)return;settled=true;resolve(value)};
    channel.subscribe(status=>{
      if(status==='SUBSCRIBED')finish(true);
      if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'||status==='CLOSED'){
        if(voiceInboxChannel===channel){voiceInboxChannel=null;voiceInboxIdentity=null}
        finish(false)
      }
    });
    setTimeout(()=>finish(false),4500)
  });
  const ready=await voiceInboxReady;
  if(!ready&&voiceInboxChannel===channel){try{channel.unsubscribe()}catch{}voiceInboxChannel=null;voiceInboxIdentity=null;voiceInboxReady=null}
  return ready
}
