/* Comunidad visual v1: fiel a la identidad eSKATE SUV */
:root{--eskate-bg:#020b12;--eskate-panel:#071723;--eskate-cyan:#00aaff;--eskate-line:#07567d;--eskate-text:#f4fbff;--eskate-muted:#8fa8b8}
body{background:radial-gradient(circle at 50% -10%,#09273a 0,#020b12 38%,#01070c 100%);color:var(--eskate-text)}
.brand{letter-spacing:.22em;color:var(--eskate-cyan);font-weight:800}
.menuCard{position:relative;overflow:hidden;border:1px solid var(--eskate-line);background:linear-gradient(180deg,#0b2130,#06131d);box-shadow:0 10px 30px rgba(0,0,0,.28)}
