.rvPtt.voxReady .rvWaveRing{border-color:rgba(85,220,255,.78);box-shadow:0 0 12px rgba(39,217,255,.28)}
.rvPtt.voxReady .rvVoiceCore{background:radial-gradient(circle at 45% 35%,rgba(54,218,255,.34),rgba(3,45,63,.9) 68%);border-color:rgba(117,232,255,.72);box-shadow:inset 0 0 17px rgba(91,224,255,.16),0 0 15px rgba(39,217,255,.22)}
.rvPtt.voxReady .rvVoiceCore b{background:#e9fbff;box-shadow:0 0 7px rgba(92,225,255,.9)}
.rvPtt.voxReady.talking .rvWaveRing{border-color:rgba(88,228,255,.95);box-shadow:0 0 15px rgba(39,217,255,.45)}
@keyframes rvVoiceIdle{0%{transform:translate(-50%,-50%) scale(.72);opacity:.2}65%{opacity:.08}100%{transform:translate(-50%,-50%) scale(1.42);opacity:0}}
@keyframes rvVoiceTalk{0%{transform:translate(-50%,-50%) scale(.7);opacity:.72}70%{opacity:.18}100%{transform:translate(-50%,-50%) scale(1.72);opacity:0}}
@keyframes rvBarsIdle{0%,100%{transform:scaleY(.72);opacity:.72}50%{transform:scaleY(1);opacity:1}}
@keyframes rvBarsTalk{0%{transform:scaleY(.55)}100%{transform:scaleY(1.35)}}
@media (prefers-reduced-motion:reduce){.rvWaveRing,.rvVoiceCore b{animation:none!important}.rvWaveRing{opacity:.2;transform:translate(-50%,-50%) scale(1.12)}}

/* Rider Voz · ajuste visual aprobado 2026-09-22
   Sube el indicador, acerca el mensaje de grupo y aumenta el pulso central.
   La lógica de color/voz sigue gobernada por .voxReady y .talking. */
.riderVoiceApp .rvAvatars{min-height:34px}
.riderVoiceApp .rvAvatars .emptyGroup{align-self:flex-start;line-height:1.15;padding-top:1px}
.riderVoiceApp .rvPtt{width:144px;height:144px;margin:-3px auto 3px;position:relative;top:-8px}
.riderVoiceApp .rvVoicePulse{width:104px;height:104px}
.riderVoiceApp .rvWaveRing{width:64px;height:64px}
.riderVoiceApp .rvVoiceCore{width:68px;height:68px;gap:5px}
.riderVoiceApp .rvVoiceCore b{width:5px;height:15px}
.riderVoiceApp .rvVoiceCore b:nth-child(2){height:24px}
.riderVoiceApp .rvVoiceCore b:nth-child(3){height:34px}
.riderVoiceApp .rvVoiceCore b:nth-child(4){height:24px}
.riderVoiceApp .rvVoiceCore b:nth-child(5){height:15px}
.riderVoiceApp .rvConsole>h2#voiceModeTitle{margin:3px 0 11px}
